const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const mahajanga = ee.Geometry.Point([46.3167, -15.7167]);
  const startDate = '2020-01-01';
  const endDate = '2020-01-31';

  // 2. Data Acquisition - CHIRPS Daily Precipitation
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(mahajanga);

  const imageCount = chirps.size().getInfo();
  console.log(`CHIRPS Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No precipitation data available for Mahajanga in January 2020.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate total precipitation
  const totalPrecip = chirps.select('precipitation').sum();

  // 4. Extract value for Mahajanga point
  const precipStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mahajanga,
    scale: 5566,
    maxPixels: 1e9
  });

  const totalMm = precipStats.get('precipitation').getInfo();

  // 5. Validation & Answer
  if (totalMm === null || totalMm === undefined || isNaN(totalMm)) {
    console.log("Calculation failed - invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  const totalInches = totalMm / 25.4;
  const threshold = 12.0;

  console.log(`Total rainfall in January 2020: ${totalMm.toFixed(2)} mm (${totalInches.toFixed(2)} inches)`);
  console.log(`Threshold: ${threshold} inches (${(threshold * 25.4).toFixed(2)} mm)`);
  console.log(`Number of days with data: ${imageCount}`);

  if (totalInches > threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
